entries[228264] = { ["name"] = "Leerengestalt", ["text"] = "Wird durch den Einsatz von 'Leereneruption' aktiviert. Verzerrt Eure Schattengestalt durch die Macht der Leere und erhöht so Euren verursachten Zauberschaden um 10%. Schließt zusätzlich die Abklingzeit von 'Gedankenschlag' ab.\n\nHält 20 Sek. lang an. Das Wirken von 'Verschlingende Seuche' erhöht die Dauer der Leerengestalt um 2.5 Sek." }
entries[228265] = { ["name"] = "Seelenkorrosion", ["text"] = "Unbegrenzte Reichweite\nSofort\nFür alle 3 Sek., die ein Spielercharakter im Brunnen der Seelen verbleibt, verlässt ein Seelenfragment den Brunnen, das 4805 Schattenschaden innerhalb von 5 Metern um den anvisierten Spielercharakter verursacht und ihn mit 'Seelenkorrosion' belegt.\n\n'Seelenkorrosion' verursacht 3 Min. lang pro Sekunde 790 Schattenschaden. Dieser Effekt ist stapelbar." }
entries[228266] = { ["name"] = "Leerenblitz", ["text"] = "Während der Dauer Eurer Leerengestalt wird Eure Fähigkeit 'Leereneruption' durch 'Leerenblitz' ersetzt:\n\nLeerenblitz\n40 Meter Reichweite\nSofort 6 Sek. Abklingzeit Requires Priest\nRequires level 23 Feuert einen Blitz aus reiner Leerenenergie auf den Gegner, der ihm (350.975% der Zaubermacht) Schattenschaden zufügt .\n\nBenötigt Leerengestalt.\n\nErzeugt 10 Wahnsinn." }
