entries[228919] = { ["name"] = "Dunkelwasserrochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Dunkelwasserrochen oder gibt ihn wieder frei.\n\nLässt sich nur unter Wasser einsetzen.\n\"Über diese scheue Rochenart ist nur wenig bekannt. Sie wurde bisher nur in den dunklen Gewässern um die Dunkelmond-Insel herum gesichtet.\"\nVerkäufer:\nGalissa Sonnentau\nZone:\nDunkelmond-Insel" }
